#!/usr/bin/env node
// scripts/ios/native-strings.cjs — ios-intl-1 Part 3 (9 November 2026; docs/ios-intl-1-report.md): THE iOS BINARY'S WORDS, GENERATED
// FROM messages/. The one source is `nativeShell.binary` in messages/<locale>.json (en-GB and every language base), so the web's words
// and the binary's cannot drift: scripts/ios-intl-1.cjs fails when a generated file differs from what this script would write.
//   node scripts/ios/native-strings.cjs           write ios/App/App/<lproj>/InfoPlist.strings + Localizable.strings, and keep the
//                                                  Xcode project's two localised groups, resource entries and known regions in step
//   node scripts/ios/native-strings.cjs --check   write nothing; exit 1 if anything is missing or differs
//
// What goes where:
//   InfoPlist.strings — every NS…UsageDescription the app's Info.plist declares (camera, Bluetooth, local network, Face ID), each
//                       from its nativeShell.binary key, plus CFBundleDisplayName = "HatchGrab" (the name is the same in every
//                       language). 🔴 Apple guideline 5.1.1: a purpose string must stay accurate in every language — the
//                       translations say exactly what the English says (back-translations: docs/i18n/back/<locale>.json).
//   Localizable.strings — the Swift shell's own words (HGBridgeViewController's offline screen), keys = NSLocalizedString keys.
// The project entries carry the fixed ids HG03… so a re-run rewrites them exactly (idempotent), never duplicates them.
'use strict'
const fs = require('fs')
const path = require('path')
const REPO = path.resolve(__dirname, '../..')
const APP = path.join(REPO, 'ios/App/App')
const PBX = path.join(REPO, 'ios/App/App.xcodeproj/project.pbxproj')

/** messages locale → the .lproj folder iOS looks for. en is the development region (CFBundleDevelopmentRegion = en). ~~zh-HK is also
 *  written as zh-Hant, so a device set to Traditional Chinese without the Hong Kong region still finds it.~~ languages-world-1 (10 November
 *  2026): zh-Hant is now Taiwan's words (zh-TW) — Apple's Traditional Chinese folder, the one a Taiwanese device reads — and zh-HK keeps its
 *  own zh-HK folder; + Turkish, Korean, Indonesian, Vietnamese, Hebrew, Icelandic and Serbian (Latin script, sr-Latn — the script the
 *  sr-RS messages are written in). */
const LPROJ = {
  'en-GB': ['en'], 'fr-FR': ['fr'], 'de-DE': ['de'], 'es-ES': ['es'], 'it-IT': ['it'], 'pt-PT': ['pt-PT'], 'pt-BR': ['pt-BR'], 'nl-NL': ['nl'],
  'sv-SE': ['sv'], 'da-DK': ['da'], 'nb-NO': ['nb'], 'pl-PL': ['pl'], 'cs-CZ': ['cs'], 'hu-HU': ['hu'], 'sk-SK': ['sk'], 'ro-RO': ['ro'],
  'hr-HR': ['hr'], 'sl-SI': ['sl'], 'fi-FI': ['fi'], 'et-EE': ['et'], 'lv-LV': ['lv'], 'lt-LT': ['lt'], 'el-GR': ['el'], 'bg-BG': ['bg'],
  'ms-MY': ['ms'], 'ja-JP': ['ja'], 'zh-HK': ['zh-HK'], 'zh-TW': ['zh-Hant'], 'th-TH': ['th'], 'ar-AE': ['ar'],
  'tr-TR': ['tr'], 'ko-KR': ['ko'], 'id-ID': ['id'], 'vi-VN': ['vi'], 'he-IL': ['he'], 'is-IS': ['is'], 'sr-RS': ['sr-Latn'],
  // languages-world-2 (11 November 2026): each new base's plain language folder, added as the language is merged (ru = Kazakhstan's
  // Russian, the only Russian file; uz and bs are Latin, their CLDR default script).
  'ru-KZ': ['ru'], 'uk-UA': ['uk'], 'kk-KZ': ['kk'], 'uz-UZ': ['uz'], 'az-AZ': ['az'], 'ka-GE': ['ka'], 'hy-AM': ['hy'], 'mn-MN': ['mn'], 'hi-IN': ['hi'], 'bn-BD': ['bn'], 'ur-PK': ['ur'],
}
const PLIST_KEYS = { NSCameraUsageDescription: 'cameraUsage', NSBluetoothAlwaysUsageDescription: 'bluetoothUsage', NSLocalNetworkUsageDescription: 'localNetworkUsage', NSFaceIDUsageDescription: 'faceIdUsage' }
const SWIFT_KEYS = ['offlineTitle', 'offlineDetail', 'retry']
const DISPLAY_NAME = 'HatchGrab'

const esc = s => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n')
const header = what => `/* ${what} — GENERATED by scripts/ios/native-strings.cjs from messages/<locale>.json nativeShell.binary. Do not edit. */\n`

function binaryOf(locale) {
  const j = JSON.parse(fs.readFileSync(path.join(REPO, 'messages', `${locale}.json`), 'utf8'))
  return j.nativeShell?.binary ?? null
}

/** Every file this script owns, with its exact content. Throws (listing them) when a language lacks a key. */
function planFiles() {
  const files = {}, missing = []
  for (const [locale, dirs] of Object.entries(LPROJ)) {
    const b = binaryOf(locale)
    const need = [...Object.values(PLIST_KEYS), ...SWIFT_KEYS]
    const gaps = need.filter(k => typeof b?.[k] !== 'string' || !b[k].trim())
    if (gaps.length) { missing.push(`${locale}: ${gaps.join(', ')}`); continue }
    const info = header('InfoPlist.strings') + `"CFBundleDisplayName" = "${DISPLAY_NAME}";\n` + Object.entries(PLIST_KEYS).map(([k, m]) => `"${k}" = "${esc(b[m])}";\n`).join('')
    const loc = header('Localizable.strings') + SWIFT_KEYS.map(k => `"${k}" = "${esc(b[k])}";\n`).join('')
    for (const d of dirs) { files[`${d}.lproj/InfoPlist.strings`] = info; files[`${d}.lproj/Localizable.strings`] = loc }
  }
  if (missing.length) throw new Error(`nativeShell.binary is incomplete:\n  ${missing.join('\n  ')}`)
  return files
}

const REGIONS = () => [...new Set(Object.values(LPROJ).flat())]
const id = (kind, n) => `HG03${kind}${String(n).padStart(16, '0')}`   // 22 characters, the same shape as the existing HG01BB… ids

/** The project file with this script's entries (re)written: everything carrying an HG03 id is removed, then written afresh. */
function planPbx(src) {
  let s = src.split('\n').filter(l => !l.includes('HG03')).join('\n')
  const regions = REGIONS()
  const groups = [['InfoPlist.strings', 'IP', 1], ['Localizable.strings', 'LS', 2]]
  const refs = [], children = {}
  for (const [name, kind] of groups) {
    children[name] = regions.map((r, i) => { const rid = id(kind, i + 1); refs.push(`\t\t${rid} /* ${r} */ = {isa = PBXFileReference; lastKnownFileType = text.plist.strings; name = ${r}; path = ${r}.lproj/${name}; sourceTree = "<group>"; };`); return rid })
  }
  const insertAfter = (marker, lines) => { const i = s.indexOf(marker); if (i < 0) throw new Error(`project file: "${marker}" not found`); const j = s.indexOf('\n', i) + 1; s = s.slice(0, j) + lines.join('\n') + '\n' + s.slice(j) }
  insertAfter('/* Begin PBXBuildFile section */', groups.map(([name, , n]) => `\t\t${id('BF', n)} /* ${name} in Resources */ = {isa = PBXBuildFile; fileRef = ${id('VG', n)} /* ${name} */; };`))
  insertAfter('/* Begin PBXFileReference section */', refs)
  insertAfter('/* PrivacyInfo.xcprivacy */,', groups.map(([name, , n]) => `\t\t\t\t${id('VG', n)} /* ${name} */,`))   // the App group's children
  insertAfter('/* PrivacyInfo.xcprivacy in Resources */,', groups.map(([name, , n]) => `\t\t\t\t${id('BF', n)} /* ${name} in Resources */,`))
  insertAfter('/* Begin PBXVariantGroup section */', groups.map(([name, kind, n]) => `\t\t${id('VG', n)} /* ${name} */ = {isa = PBXVariantGroup; children = (${children[name].map((c, i) => `${c} /* ${regions[i]} */`).join(', ')}, ); name = ${name}; sourceTree = "<group>"; };`))
  s = s.replace(/knownRegions = \([\s\S]*?\);/, `knownRegions = (\n${[...regions, 'Base'].map(r => `\t\t\t\t${/^[A-Za-z]+$/.test(r) ? r : `"${r}"`},`).join('\n')}\n\t\t\t);`)
  return s
}

function run(check) {
  const files = planFiles(), problems = []
  for (const [rel, content] of Object.entries(files)) {
    const f = path.join(APP, rel)
    const now = fs.existsSync(f) ? fs.readFileSync(f, 'utf8') : null
    if (now === content) continue
    if (check) problems.push(`${rel} ${now === null ? 'missing' : 'differs from messages'}`)
    else { fs.mkdirSync(path.dirname(f), { recursive: true }); fs.writeFileSync(f, content) }
  }
  // a stray .strings file (a language removed from LPROJ, or a hand-made one) is a drift too
  for (const d of fs.readdirSync(APP).filter(d => d.endsWith('.lproj') && d !== 'Base.lproj')) for (const f of fs.readdirSync(path.join(APP, d))) if (!files[`${d}/${f}`]) problems.push(`${d}/${f} is not generated by this script`)
  const pbxNow = fs.readFileSync(PBX, 'utf8'), pbxWant = planPbx(pbxNow)
  if (pbxNow !== pbxWant) { if (check) problems.push('project.pbxproj: the localised groups / known regions are not what this script writes'); else fs.writeFileSync(PBX, pbxWant) }
  return { files: Object.keys(files).length, regions: REGIONS(), problems }
}

module.exports = { LPROJ, PLIST_KEYS, SWIFT_KEYS, planFiles, planPbx, run }
if (require.main === module) {
  try {
    const check = process.argv.includes('--check')
    const r = run(check)
    if (r.problems.length) { console.log(`🔴 ${r.problems.length} problem(s):\n  ${r.problems.join('\n  ')}`); process.exit(1) }
    console.log(`${check ? '✓ in step' : '✓ written'}: ${r.files} .strings files in ${r.regions.length} languages (${r.regions.join(', ')})`)
  } catch (e) { console.error(`🔴 ${e.message}`); process.exit(1) }
}
